package ru.aston.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import ru.aston.model.dto.DishDto;

import java.util.List;

@RestController
@RequestMapping("/api/v1/dishes")
public class DishController {

    @Autowired
    private DishService dishService;

    @Autowired
    private UserServiceClient userServiceClient; // клиент для взаимодействия с User сервисом

    @GetMapping
    public ResponseEntity<List<DishDto>> getAllDishes() {
        List<DishDto> dishes = dishService.getAllDishes();
        return ResponseEntity.ok(dishes);
    }

    @GetMapping("/search")
    public ResponseEntity<List<DishDto>> searchDishes(@RequestParam String query) {
        List<DishDto> dishes = dishService.searchDishes(query);
        return ResponseEntity.ok(dishes);
    }

    @PostMapping("/add-to-cart")
    public ResponseEntity<String> addToCart(@RequestParam Long dishId, @RequestHeader("Authorization") String token) {
        if (!isUserAuthenticated(token)) {
            return ResponseEntity.status(HttpStatus.FORBIDDEN).body("You need to log in to add to the cart.");
        }

        Long userId = getUserIdFromToken(token); // Извлекаем информацию о пользователе из токена
        dishService.addToCart(dishId, userId);
        return ResponseEntity.ok("Dish added to cart.");
    }

    // Метод для проверки авторизации пользователя
    private boolean isUserAuthenticated(String token) {
        // Логика для проверки JWT токена
        return token != null && !token.isEmpty();
    }

    // Получаем id пользователя из токена
    private Long getUserIdFromToken(String token) {
        // Декодируем JWT и извлекаем id пользователя
        return 123L; // пример
    }
}

